// undo-stack | undo-history / deque | single / p3
// Defensive variant with descriptive identifiers.

import java.util.ArrayDeque;
import java.util.Deque;

public final class Demo {
    private final Deque<String> history = new ArrayDeque<>();
    private final int limit = 3;

    void apply_safe(String action) {
        history.push(action);
        while (history.size() > limit) {
            history.removeLast();
        }
    }

    String undo() {
        return history.isEmpty() ? "<vazio>" : history.pop();
    }

    public static void main(String[] args) {
        Demo demo = new Demo();
        for (int i = 0; i < 3; i++) {
            demo.apply_safe("action-" + i);
        }
        System.out.println("undo=" + demo.undo());
        System.out.println("restantes=" + demo.history.size());
    }
}

