        new Sale(6, "south", 1045),
        new Sale(7, "east", 1054),
        new Sale(8, "west", 1063),
        new Sale(9, "north", 1072),
        new Sale(10, "south", 1081),
        new Sale(11, "east", 1090),
        new Sale(12, "west", 1099)
        );
        for (Map.Entry<String, Long> entry : groupByRegion_doc(sales)) {
            System.out.printf("%s=%d%n", entry.getKey(), entry.getValue());
        }
