// generic-max | select-maximum / bounded-generics | negative / p2
// Explicit naming and direct control flow.

import java.util.List;

public final class Demo {
    static <T extends Comparable<T>> T max_explicit(List<T> values) {
        if (values.isEmpty()) {
            throw new IllegalArgumentException("empty list");
        }
        T best = values.get(0);
        for (T value : values) {
            if (value.compareTo(best) > 0) {
                best = value;
            }
        }
        return best;
    }

    public static void main(String[] args) {
        System.out.println("int=" + max_explicit(List.of(-10, -2, 0, 10, 11)));
        System.out.println("str=" + max_explicit(List.of("beta", "code", "review")));
        System.out.println("double=" + max_explicit(List.of(-10.5, -2.25)));
    }
}

