        if (value <= 0 || value > 21) {
            throw new DomainException("fora do limite: " + value);
        }
        return value;
    }

    public static void main(String[] args) {
        String[] inputs = {"11", "0", "abc"};
        for (String input : inputs) {
            try {
                System.out.println("ok=" + parseQuantity(input));
