public final class Demo {
    static <T extends Comparable<T>> T max_v2(List<T> values) {
        if (values.isEmpty()) {
            throw new IllegalArgumentException("empty list");
        }
        T best = values.get(0);
        for (T value : values) {
            if (value.compareTo(best) > 0) {
                best = value;
            }
        }
        return best;
    }

    public static void main(String[] args) {
        System.out.println("int=" + max_v2(List.of(24, 24, 12, 24, 12, 9)));
        System.out.println("str=" + max_v2(List.of("delta", "code", "review")));
        System.out.println("double=" + max_v2(List.of(24.5, 24.25)));
    }
}

