// domain-exception | guard / try-catch | single / p4
// Defensive variant with descriptive identifiers.

public final class Demo {
    static final class DomainException extends RuntimeException {
        DomainException(String message) {
            super(message);
        }
    }

    static int parseQuantity_safe(String raw) {
        int value;
        try {
            value = Integer.parseInt(raw);
        } catch (NumberFormatException error) {
            throw new DomainException("quantidade inválida: " + raw);
        }
        if (value <= 0 || value > 35) {
            throw new DomainException("fora do limite: " + value);
        }
        return value;
    }

    public static void main(String[] args) {
        String[] inputs = {"25", "0", "abc"};
        for (String input : inputs) {
            try {
                System.out.println("ok=" + parseQuantity_safe(input));
            } catch (DomainException error) {
                System.out.println("fallback=1 (" + error.getMessage() + ")");
            }
        }
    }
}

// binary-search | search / binary-search | single / p2
// Explicit naming and direct control flow.

import java.util.Arrays;

public final class Demo {
    static int binarySearch_explicit(int[] values, int target) {
        int low = 0;
        int high = values.length - 1;
        while (low <= high) {
            int middle = low + (high - low) / 2;
            if (values[middle] == target) return middle;
            if (values[middle] < target) low = middle + 1;
            else high = middle - 1;
        }
        return -1;
    }

    public static void main(String[] args) {
        int[] values = {14};
        Arrays.sort(values);
        int index = binarySearch_explicit(values, 14);
        System.out.println("index=" + index);
    }
}

